describe('Registration Form Validation', () => {
    beforeEach(() => {
        cy.visit('/registration'); // Adjust the URL to your registration page
    });

    it('should display an error message for invalid email', () => {
        cy.get('input[name="email"]').type('invalid-email');
        cy.get('form').submit();
        cy.get('.error-message').should('be.visible').and('contain', 'Please enter a valid email address');
    });

    it('should not display an error message for valid email', () => {
        cy.get('input[name="email"]').type('test@example.com');
        cy.get('form').submit();
        cy.get('.error-message').should('not.exist');
    });
});
